/* Giai đoạn 2 · Chặng 2 – Ngữ pháp Part 5 cốt lõi (bài 3–7; bài 2 nằm trong stage2.js) */
TOEIC.addLesson({
  id: "s2-l3", stage: 2, unit: "u2", order: 2, minutes: 25, title: "Bài 3. Danh từ chỉ người & vật, tính từ -ed/-ing, danh từ ghép",
  sections: [
    { h: "Danh từ chỉ người hay chỉ vật / sự việc?", html: "<p>Part 5 rất hay cho 4 lựa chọn cùng gốc, trong đó có <b>hai danh từ</b>: một chỉ <b>người</b>, một chỉ <b>vật / sự việc</b>. Cả hai đều đúng từ loại, nên phải xét <b>nghĩa</b> và <b>số ít / số nhiều</b>.</p><table><tr><th>Động từ</th><th>Danh từ chỉ người</th><th>Danh từ chỉ vật / sự việc</th></tr><tr><td>apply (nộp đơn)</td><td><b>applicant</b> (người nộp đơn)</td><td><b>application</b> (đơn xin; việc nộp đơn)</td></tr><tr><td>employ (thuê, tuyển)</td><td><b>employer</b> (chủ, người thuê) · <b>employee</b> (nhân viên)</td><td><b>employment</b> (việc làm, sự tuyển dụng – không đếm được)</td></tr><tr><td>attend (tham dự; phục vụ)</td><td><b>attendee</b> (người dự) · <b>attendant</b> (nhân viên phục vụ)</td><td><b>attendance</b> (sự có mặt; số người dự)</td></tr><tr><td>supervise (giám sát)</td><td><b>supervisor</b></td><td><b>supervision</b></td></tr><tr><td>participate (tham gia)</td><td><b>participant</b></td><td><b>participation</b></td></tr><tr><td>consult (tư vấn)</td><td><b>consultant</b></td><td><b>consultation</b></td></tr></table><p>Cách chọn: hỏi “chủ ngữ / tân ngữ này <b>làm được hành động</b> trong câu không?”. <i>Applications must be <b>submitted</b></i> (đơn được nộp) – <i><b>Applicants</b> must submit their résumés</i> (người nộp đơn nộp hồ sơ). Đuôi <b>-er/-or/-ant/-ee/-ist</b> thường là người; <b>-tion/-ment/-ance/-ence</b> là vật / sự việc.</p>" },
    { h: "Tính từ -ed và -ing", html: "<p><b>V-ing</b> (tính từ chủ động) = <b>gây ra</b> cảm xúc / đặc điểm → thường mô tả <b>vật, sự việc</b>. <b>V-ed</b> (tính từ bị động) = <b>cảm thấy</b> / bị tác động → thường mô tả <b>người</b>.</p><table><tr><th>-ing (gây ra)</th><th>-ed (cảm thấy)</th><th>Ví dụ</th></tr><tr><td>interesting</td><td>interested (in)</td><td>an <b>interesting</b> offer · She is <b>interested</b> in the offer.</td></tr><tr><td>satisfying</td><td>satisfied (with)</td><td>a <b>satisfying</b> result · <b>satisfied</b> customers</td></tr><tr><td>confusing</td><td>confused</td><td>The form is <b>confusing</b>. · Applicants were <b>confused</b>.</td></tr><tr><td>disappointing</td><td>disappointed</td><td><b>disappointing</b> sales · a <b>disappointed</b> manager</td></tr><tr><td>exhausting</td><td>exhausted</td><td>an <b>exhausting</b> trip · <b>exhausted</b> staff</td></tr><tr><td>impressive (không có “impressing”)</td><td>impressed (by/with)</td><td>an <b>impressive</b> résumé · We were <b>impressed</b>.</td></tr></table><p>Ngoài cảm xúc, quy tắc này áp dụng cho mọi phân từ đứng trước danh từ: danh từ <b>tự làm</b> → V-ing (<i><b>rising</b> costs, <b>existing</b> customers, a <b>leading</b> firm</i>); danh từ <b>bị làm</b> → V-ed (<i>the <b>attached</b> file, an <b>experienced</b> lawyer, a <b>detailed</b> report, <b>limited</b> space</i>).</p>" },
    { h: "Danh từ ghép & danh từ đếm được số ít", html: "<p><b>Danh từ ghép = danh từ + danh từ</b>: danh từ đầu đóng vai trò như tính từ và thường để <b>số ít</b>: <i>safety regulations, job applicants, application form, employee benefits, registration fee, expiration date, attendance record, <b>customer satisfaction survey</b></i>.</p><p>Ngoại lệ hay gặp – một số danh từ <b>luôn có -s</b> kể cả khi đứng đầu: <b>sales</b> figures / sales representative, <b>savings</b> account, <b>customs</b> office, <b>earnings</b> report, <b>benefits</b> package.</p><p><b>Danh từ đếm được số ít không đứng một mình</b>: phải có <b>a/an, the, this, his, each, every…</b> phía trước. Sai: <i>She submitted application.</i> → Đúng: <i>She submitted <b>an application</b></i> hoặc <i>She submitted <b>applications</b></i>. Danh từ chỉ người như applicant, employee, consultant luôn đếm được. Các danh từ không đếm được như <b>employment, equipment, information, advice, furniture</b> không dùng a/an và không thêm -s.</p>" },
    { h: "Mẹo làm bài TOEIC", html: "<ul><li>Thấy hai danh từ người / vật trong lựa chọn → xét <b>động từ chính</b>: “___ must be submitted / reviewed / approved” thường là vật; “___ must submit / attend / sign” thường là người.</li><li>Xét <b>động từ chia</b> để biết số ít / số nhiều: <i>Employee ___ <b>has</b> increased</i> → attendance (số ít), không phải attendees.</li><li>Chỗ trống <b>giữa từ hạn định và danh từ</b> (the ___ survey) mà có lựa chọn là danh từ → nghĩ đến <b>danh từ ghép</b> trước khi chọn tính từ.</li><li>Hỏi “ai / cái gì <b>gây ra</b> cảm xúc?” → -ing; “ai <b>cảm thấy</b>?” → -ed. Sau <b>find + tân ngữ</b> mô tả sự việc → -ing: <i>found the session <b>confusing</b></i>.</li><li>Danh từ đếm được số ít mà không có từ hạn định đứng trước → <b>sai</b>, loại ngay.</li></ul>" }
  ],
  examples: [
    { en: "All <b>applicants</b> must submit their <b>applications</b> online by May 15.", vi: "Tất cả người nộp đơn phải nộp đơn trực tuyến trước ngày 15 tháng Năm." },
    { en: "The <b>employer</b> provides health insurance to all full-time <b>employees</b>.", vi: "Chủ lao động cung cấp bảo hiểm y tế cho tất cả nhân viên toàn thời gian." },
    { en: "<b>Attendance</b> at the safety training is mandatory for every new hire.", vi: "Việc có mặt tại buổi đào tạo an toàn là bắt buộc với mọi nhân viên mới." },
    { en: "The parking <b>attendant</b> showed the job candidates where to leave their cars.", vi: "Nhân viên giữ xe chỉ cho các ứng viên chỗ để xe." },
    { en: "The board was <b>disappointed</b> because the quarterly results were <b>disappointing</b>.", vi: "Hội đồng quản trị thất vọng vì kết quả quý đáng thất vọng." },
    { en: "The <b>customer satisfaction survey</b> will be sent to all clients next week.", vi: "Bản khảo sát mức độ hài lòng của khách hàng sẽ được gửi cho mọi khách hàng vào tuần sau." }
  ],
  vocab: [
    "onboarding|n|/ˈɒnbɔːdɪŋ/|quá trình tiếp nhận, hội nhập nhân viên mới|induction|Onboarding usually takes about two weeks.|Quá trình hội nhập nhân viên mới thường mất khoảng hai tuần.",
    "employment|n|/ɪmˈplɔɪmənt/|việc làm; sự tuyển dụng|work|The contract states the terms of employment.|Hợp đồng nêu rõ các điều khoản tuyển dụng.",
    "attendance|n|/əˈtendəns/|sự có mặt, sự tham dự; số người dự|presence|Attendance at the monthly meeting is required.|Bắt buộc phải có mặt tại cuộc họp hằng tháng.",
    "vacancy|n|/ˈveɪkənsi/|vị trí còn trống|opening|We have a vacancy for a payroll clerk.|Chúng tôi có một vị trí trống cho nhân viên tính lương.",
    "probation|n|/prəˈbeɪʃn/|thời gian thử việc|trial period|New staff are on probation for two months.|Nhân viên mới phải thử việc hai tháng.",
    "orientation|n|/ˌɔːriənˈteɪʃn/|buổi định hướng cho nhân viên mới|induction|The orientation for new hires starts at 9 a.m.|Buổi định hướng cho nhân viên mới bắt đầu lúc 9 giờ sáng.",
    "compensation|n|/ˌkɒmpenˈseɪʃn/|lương thưởng, đãi ngộ; tiền bồi thường|pay|The compensation package includes a yearly bonus.|Gói đãi ngộ bao gồm một khoản thưởng hằng năm.",
    "incentive|n|/ɪnˈsentɪv/|khoản khuyến khích, ưu đãi|bonus|Employees receive an incentive for perfect attendance.|Nhân viên nhận khoản thưởng khuyến khích nếu đi làm đầy đủ.",
    "turnover|n|/ˈtɜːnəʊvə(r)/|tỷ lệ nghỉ việc (thay người); doanh thu|—|Staff turnover has fallen since salaries were raised.|Tỷ lệ nghỉ việc đã giảm từ khi tăng lương.",
    "appraisal|n|/əˈpreɪzl/|sự đánh giá (năng lực nhân viên)|evaluation|Performance appraisals are held every December.|Việc đánh giá hiệu quả công việc diễn ra vào mỗi tháng Mười Hai.",
    "recruiter|n|/rɪˈkruːtə(r)/|nhân viên tuyển dụng|headhunter|A recruiter called me about a job in Hanoi.|Một nhân viên tuyển dụng đã gọi cho tôi về một công việc ở Hà Nội.",
    "job description|n|/ˈdʒɒb dɪˌskrɪpʃn/|bản mô tả công việc|—|Please read the job description carefully before applying.|Vui lòng đọc kỹ bản mô tả công việc trước khi ứng tuyển."
  ],
  exercises: [
    { id: "s2-l3-ex0", p: 5, lvl: 2, q: "All ___ for the marketing position must be submitted by Friday.", c: ["applicants", "applications", "apply", "applying"], a: 1, e: "“must be submitted” (được nộp) → chủ ngữ là vật: <b>applications</b> (đơn xin). “applicants” là người, không thể “được nộp”.", t: "tu-loai" },
    { id: "s2-l3-ex1", p: 5, lvl: 2, q: "The company has decided to hire two more ___ to handle the increased workload.", c: ["employment", "employees", "employers", "employ"], a: 1, e: "Sau “two more” cần danh từ số nhiều đếm được, và người được thuê để làm việc là <b>employees</b>. “employers” là chủ lao động; “employment” không đếm được.", t: "tu-loai" },
    { id: "s2-l3-ex2", p: 5, lvl: 2, q: "Ms. Kim was very ___ with the results of the employee survey.", c: ["satisfy", "satisfying", "satisfied", "satisfaction"], a: 2, e: "Người (Ms. Kim) <b>cảm thấy</b> hài lòng → tính từ -ed: <b>satisfied</b> with. “satisfying” mô tả sự việc gây ra sự hài lòng.", t: "tu-loai" },
    { id: "s2-l3-ex3", p: 5, lvl: 2, q: "Many participants found the new appraisal process ___.", c: ["confuse", "confusing", "confused", "confusion"], a: 1, e: "find + tân ngữ + tính từ; quy trình <b>gây ra</b> sự bối rối → <b>confusing</b>. “confused” dùng cho người cảm thấy bối rối.", t: "tu-loai" },
    { id: "s2-l3-ex4", p: 5, lvl: 2, q: "Please complete the customer ___ survey and return it to the front desk.", c: ["satisfy", "satisfied", "satisfaction", "satisfying"], a: 2, e: "Danh từ ghép cố định <b>customer satisfaction survey</b> (khảo sát mức độ hài lòng của khách hàng): chỗ trống là danh từ đứng trước danh từ “survey”.", t: "tu-loai" },
    { id: "s2-l3-ex5", p: 5, lvl: 2, q: "Employee ___ at the monthly workshops has increased since free lunches were introduced.", c: ["attendance", "attendants", "attendees", "attend"], a: 0, e: "Động từ “has increased” là số ít, và nghĩa là “sự có mặt” của nhân viên → <b>attendance</b> (không đếm được). “attendants”, “attendees” là số nhiều, phải đi với “have”.", t: "tu-loai" },
    { id: "s2-l3-ex6", p: 5, lvl: 2, q: "Ms. Ruiz submitted ___ for the vacancy yesterday and will be interviewed next week.", c: ["application", "an application", "applicant", "applying"], a: 1, e: "“application” là danh từ đếm được số ít nên cần từ hạn định → <b>an application</b>. “applicant” là người, sai nghĩa và cũng thiếu mạo từ.", t: "tu-loai" },
    { id: "s2-l3-ex7", p: 5, lvl: 2, q: "The ___ figures for the third quarter will be announced at the board meeting.", c: ["sale", "sales", "sold", "selling"], a: 1, e: "Cụm cố định <b>sales figures</b> (số liệu doanh số): “sales” là ngoại lệ luôn giữ -s khi đứng đầu danh từ ghép.", t: "tu-loai" },
    { id: "s2-l3-ex8", p: 5, lvl: 2, q: "We have hired an ___ consultant with twenty years of practice in labor law.", c: ["experience", "experiencing", "experienced", "experiences"], a: 2, e: "Trước danh từ “consultant” cần tính từ; người <b>có kinh nghiệm</b> → <b>experienced</b>. “experiencing” không dùng làm tính từ với nghĩa này.", t: "tu-loai" },
    { id: "s2-l3-ex9", p: 2, lvl: 2, say: "Did you find the orientation session useful?", c: ["Yes, the speakers were very interesting.", "Yes, I was very interesting.", "The session room is on the third floor."], a: 0, e: "Hỏi buổi định hướng có hữu ích không → <b>Yes, the speakers were very interesting</b> (diễn giả gây hứng thú). “I was very interesting” là bẫy -ing/-ed (tôi là người thú vị – sai ý); câu còn lại lặp từ “session”.", t: "hoi-dap" }
  ]
});

TOEIC.addLesson({
  id: "s2-l4", stage: 2, unit: "u2", order: 3, minutes: 25, title: "Bài 4. Hòa hợp chủ ngữ – động từ",
  sections: [
    { h: "Tìm chủ ngữ thật trong chủ ngữ dài", html: "<p>TOEIC hay chèn một cụm dài giữa chủ ngữ và động từ để đánh lừa. Hãy <b>gạch bỏ</b> phần chen giữa rồi chia động từ theo <b>danh từ chính</b>:</p><ul><li><b>Cụm giới từ</b>: <i>The <b>list</b> [of approved vendors] <b>is</b> updated monthly.</i> – <i>The <b>results</b> [of the survey] <b>are</b> ready.</i></li><li><b>Mệnh đề quan hệ</b>: <i>The <b>documents</b> [that the lawyer sent last week] <b>need</b> your signature.</i></li><li><b>Cụm phân từ</b>: <i>The <b>manager</b> [responsible for hiring interns] <b>reviews</b> every résumé.</i></li><li><b>along with / together with / as well as / in addition to / accompanied by</b> + danh từ <b>không</b> làm chủ ngữ thành số nhiều: <i>Ms. Lopez, <b>along with</b> two colleagues, <b>plans</b> to attend.</i> (khác với <i>Ms. Lopez <b>and</b> two colleagues <b>plan</b>…</i>)</li></ul>" },
    { h: "Bảng chủ ngữ đặc biệt", html: "<table><tr><th>Chủ ngữ</th><th>Động từ</th><th>Ví dụ</th></tr><tr><td><b>each / every</b> + N số ít; <b>each of</b> + N số nhiều</td><td>số ít</td><td><i>Each of the managers <b>has</b> a parking space.</i></td></tr><tr><td><b>a number of</b> + N số nhiều (= nhiều)</td><td>số nhiều</td><td><i>A number of staff <b>have</b> asked for leave.</i></td></tr><tr><td><b>the number of</b> + N số nhiều (= con số)</td><td>số ít</td><td><i>The number of complaints <b>has</b> fallen.</i></td></tr><tr><td><b>either</b> A <b>or</b> B / <b>neither</b> A <b>nor</b> B / <b>not only</b> A <b>but also</b> B</td><td>theo <b>B</b> (danh từ gần động từ)</td><td><i>Neither the CEO nor the directors <b>were</b> present.</i></td></tr><tr><td><b>both</b> A <b>and</b> B</td><td>số nhiều</td><td><i>Both the contract and the invoice <b>are</b> attached.</i></td></tr><tr><td>Danh từ <b>không đếm được</b>: information, equipment, furniture, advice, luggage, feedback</td><td>số ít</td><td><i>All the information <b>is</b> confidential.</i></td></tr><tr><td><b>V-ing / To V</b> làm chủ ngữ</td><td>số ít</td><td><i>Reviewing contracts <b>takes</b> time.</i></td></tr><tr><td>Số tiền, thời gian, khoảng cách</td><td>số ít</td><td><i>Five thousand dollars <b>is</b> the limit.</i></td></tr><tr><td><b>one of the</b> + N số nhiều</td><td>số ít</td><td><i>One of the applicants <b>is</b> from Japan.</i></td></tr></table>" },
    { h: "There is / are, all of / most of và chữ -s đánh lừa", html: "<ul><li><b>There is</b> + danh từ số ít / không đếm được; <b>There are</b> + danh từ số nhiều. Động từ chia theo danh từ <b>đứng sau</b>: <i>There <b>are</b> several issues to discuss.</i> – <i>There <b>has been</b> a change in the schedule.</i></li><li><b>all / most / some / half / none of</b> + N: chia theo N. <i>Most of the <b>staff</b> are…</i> nhưng <i>Most of the <b>equipment</b> is…</i></li><li>Danh từ tận cùng -s nhưng <b>số ít</b>: news, economics, a series. Ngược lại, <b>people, staff (khi chỉ các nhân viên), police</b> thường chia số nhiều.</li><li>Trong mệnh đề quan hệ, động từ chia theo danh từ <b>ngay trước</b> who / which / that: <i>employees who <b>work</b> overtime</i>, <i>an employee who <b>works</b> overtime</i>.</li></ul>" },
    { h: "Mẹo làm bài TOEIC", html: "<ul><li>Bốn lựa chọn chỉ khác nhau ở <b>is / are, has / have, -s / không -s</b> → đây là câu hòa hợp. Tìm danh từ chính, <b>bỏ qua</b> mọi thứ nằm sau of, in, for, with, along with, as well as, who, that.</li><li>Thấy <b>a number of</b> → số nhiều; <b>the number of</b> → số ít. Đề rất hay cho cả hai trong cùng một bài.</li><li>Thấy <b>either…or / neither…nor</b> → nhìn danh từ <b>sau or / nor</b>.</li><li>Chủ ngữ bắt đầu bằng <b>V-ing</b> (Reviewing, Hiring, Complying with…) → động từ số ít.</li><li>Nhớ kiểm tra cả <b>chủ động / bị động</b> và <b>thì</b>: một lựa chọn có thể đúng số nhưng sai dạng.</li></ul>" }
  ],
  examples: [
    { en: "The results of the employee survey <b>are</b> posted on the intranet.", vi: "Kết quả khảo sát nhân viên được đăng trên mạng nội bộ." },
    { en: "<b>Each</b> new employee <b>receives</b> a copy of the employee handbook.", vi: "Mỗi nhân viên mới nhận một cuốn sổ tay nhân viên." },
    { en: "<b>A number of</b> staff members <b>have</b> applied for overtime, but <b>the number of</b> approved requests <b>is</b> small.", vi: "Nhiều nhân viên đã xin làm thêm giờ, nhưng số đơn được duyệt thì ít." },
    { en: "Either the HR manager or her assistants <b>are</b> going to process your request.", vi: "Hoặc trưởng phòng nhân sự hoặc các trợ lý của cô ấy sẽ xử lý yêu cầu của bạn." },
    { en: "The CEO, <b>as well as</b> the regional directors, <b>is</b> attending the compliance meeting.", vi: "Giám đốc điều hành, cùng với các giám đốc khu vực, sẽ dự cuộc họp về tuân thủ." },
    { en: "<b>Complying</b> with safety regulations <b>is</b> everyone's responsibility.", vi: "Tuân thủ quy định an toàn là trách nhiệm của mọi người." }
  ],
  vocab: [
    "regulation|n|/ˌreɡjuˈleɪʃn/|quy định|rule|The safety regulations apply to every employee.|Các quy định an toàn áp dụng cho mọi nhân viên.",
    "compliance|n|/kəmˈplaɪəns/|sự tuân thủ|conformity|Compliance with company policy is checked every year.|Việc tuân thủ chính sách công ty được kiểm tra hằng năm.",
    "procedure|n|/prəˈsiːdʒə(r)/|thủ tục, quy trình|process|The procedure for requesting leave is simple.|Thủ tục xin nghỉ phép rất đơn giản.",
    "employee handbook|n|/ɪmˌplɔɪˈiː ˈhændbʊk/|sổ tay nhân viên|staff manual|Every new hire receives a copy of the employee handbook.|Mỗi nhân viên mới đều nhận một cuốn sổ tay nhân viên.",
    "dress code|n|/ˈdres kəʊd/|quy định về trang phục|—|The dress code is described in the employee handbook.|Quy định về trang phục được mô tả trong sổ tay nhân viên.",
    "leave of absence|n|/ˌliːv əv ˈæbsəns/|kỳ nghỉ dài có phép|time off|She has requested a three-month leave of absence.|Cô ấy đã xin nghỉ phép ba tháng.",
    "entitled|adj|/ɪnˈtaɪtld/|được hưởng, có quyền (+ to)|eligible|Full-time staff are entitled to fifteen days of paid leave.|Nhân viên toàn thời gian được hưởng mười lăm ngày nghỉ phép có lương.",
    "premises|n|/ˈpremɪsɪz/|khuôn viên, cơ sở (của công ty)|site|Smoking is not allowed anywhere on the premises.|Không được hút thuốc ở bất cứ đâu trong khuôn viên.",
    "authorization|n|/ˌɔːθəraɪˈzeɪʃn/|sự cho phép, sự ủy quyền|permission|Each purchase over $500 requires written authorization.|Mỗi khoản mua trên 500 đô la cần có sự cho phép bằng văn bản.",
    "timesheet|n|/ˈtaɪmʃiːt/|bảng chấm công|time card|Timesheets are due every Friday afternoon.|Bảng chấm công phải nộp vào mỗi chiều thứ Sáu.",
    "headcount|n|/ˈhedkaʊnt/|số lượng nhân sự|staff numbers|The headcount in our branch has grown to 80.|Số nhân sự ở chi nhánh chúng tôi đã tăng lên 80 người.",
    "benefits package|n|/ˈbenɪfɪts ˌpækɪdʒ/|gói phúc lợi|perks|The benefits package includes health insurance.|Gói phúc lợi bao gồm bảo hiểm y tế."
  ],
  exercises: [
    { id: "s2-l4-ex0", p: 5, lvl: 2, q: "The list of approved vendors ___ updated every six months.", c: ["is", "are", "have", "be"], a: 0, e: "Chủ ngữ chính là “The list” (số ít); “of approved vendors” chỉ là cụm giới từ → <b>is</b> updated.", t: "hoa-hop" },
    { id: "s2-l4-ex1", p: 5, lvl: 2, q: "Each department manager ___ required to submit a budget proposal by June 1.", c: ["is", "are", "were", "being"], a: 0, e: "<b>Each</b> + danh từ số ít → động từ số ít: <b>is</b> required.", t: "hoa-hop" },
    { id: "s2-l4-ex2", p: 5, lvl: 2, q: "A number of employees ___ requested flexible working hours this year.", c: ["has", "have", "having", "to have"], a: 1, e: "<b>A number of</b> + N số nhiều = “nhiều …” → động từ số nhiều: <b>have</b> requested.", t: "hoa-hop" },
    { id: "s2-l4-ex3", p: 5, lvl: 2, q: "The number of job applicants ___ risen sharply since the new benefits package was announced.", c: ["has", "have", "having", "are"], a: 0, e: "<b>The number of</b> = con số (một con số) → động từ số ít: <b>has</b> risen. “are risen” sai vì rise không có bị động.", t: "hoa-hop" },
    { id: "s2-l4-ex4", p: 5, lvl: 2, q: "Neither the director nor the board members ___ aware of the change in the regulation.", c: ["was", "were", "is", "being"], a: 1, e: "neither A nor B → động từ chia theo B (“the board members”, số nhiều) → <b>were</b>.", t: "hoa-hop" },
    { id: "s2-l4-ex5", p: 5, lvl: 2, q: "Ms. Lopez, along with two of her colleagues, ___ to attend the legal seminar in Hanoi.", c: ["plan", "plans", "planning", "are planning"], a: 1, e: "“along with two of her colleagues” không làm chủ ngữ thành số nhiều; chủ ngữ thật là Ms. Lopez → <b>plans</b>.", t: "hoa-hop" },
    { id: "s2-l4-ex6", p: 5, lvl: 2, q: "All the information about overtime pay ___ in the employee handbook.", c: ["is included", "are included", "include", "including"], a: 0, e: "“information” không đếm được → số ít; thông tin “được đưa vào” → bị động: <b>is included</b>.", t: "hoa-hop" },
    { id: "s2-l4-ex7", p: 5, lvl: 2, q: "Reviewing contracts carefully ___ costly legal mistakes.", c: ["prevent", "prevents", "preventing", "to prevent"], a: 1, e: "Chủ ngữ là cụm V-ing “Reviewing contracts carefully” → động từ số ít: <b>prevents</b>. “contracts” không phải chủ ngữ.", t: "hoa-hop" },
    { id: "s2-l4-ex8", p: 5, lvl: 2, q: "There ___ several issues that the legal team needs to discuss before the contract is signed.", c: ["is", "are", "has", "be"], a: 1, e: "Sau There, động từ chia theo danh từ đứng sau: “several issues” số nhiều → <b>are</b>.", t: "hoa-hop" },
    { id: "s2-l4-ex9", say: "Every employee in the sales and marketing departments is invited to the training session.", q: "Nghe và chọn ý đúng với câu bạn nghe.", c: ["Tất cả nhân viên của phòng kinh doanh và phòng marketing đều được mời dự buổi đào tạo.", "Chỉ trưởng phòng kinh doanh và trưởng phòng marketing được mời dự đào tạo.", "Mỗi phòng chỉ được cử một nhân viên đi đào tạo.", "Nhân viên hai phòng sẽ tự tổ chức buổi đào tạo."], a: 0, e: "“<b>Every employee</b> … <b>is invited</b>” = mọi nhân viên (của hai phòng) đều được mời. Chú ý: dù có “departments” số nhiều, động từ vẫn là “is” vì chủ ngữ là “Every employee”.", t: "hoa-hop" }
  ]
});

TOEIC.addLesson({
  id: "s2-l5", stage: 2, unit: "u2", order: 4, minutes: 25, title: "Bài 5. Thì nâng cao & dấu hiệu nhận biết",
  sections: [
    { h: "Quá khứ hoàn thành & tương lai hoàn thành", html: "<p><b>Quá khứ hoàn thành: S + had + V3</b> – việc xảy ra <b>trước</b> một việc / một mốc khác trong quá khứ.</p><ul><li><i><b>By the time</b> the lawyer <b>arrived</b>, both parties <b>had</b> already <b>signed</b> the agreement.</i></li><li><i>The contract <b>had expired</b> <b>before</b> anyone <b>noticed</b> it.</i></li></ul><p><b>Tương lai hoàn thành: S + will have + V3</b> – việc sẽ <b>xong trước</b> một mốc trong tương lai.</p><ul><li><i><b>By next month</b>, we <b>will have hired</b> all the seasonal staff.</i></li><li><i><b>By the time</b> the auditors <b>arrive</b>, we <b>will have prepared</b> every document.</i></li></ul><p>Cặp dấu hiệu quan trọng: <b>by the time + quá khứ đơn</b> → had V3; <b>by the time + hiện tại đơn</b> → will have V3. <b>By + mốc tương lai</b> (by next Friday, by the end of this year) → will have V3.</p>" },
    { h: "Hiện tại hoàn thành tiếp diễn", html: "<p><b>S + have / has been + V-ing</b> – việc bắt đầu trong quá khứ, <b>vẫn đang tiếp diễn</b> đến bây giờ, nhấn mạnh <b>thời lượng</b>. Thường đi với <b>for, since, all day, lately, recently</b>.</p><ul><li><i>The two firms <b>have been negotiating</b> the merger <b>since</b> March.</i> (vẫn đang đàm phán)</li><li><i>Ms. Ito <b>has been working</b> on the amendment <b>for</b> three hours.</i></li></ul><table><tr><th>Thì</th><th>Công thức</th><th>Dấu hiệu</th></tr><tr><td>Hiện tại hoàn thành</td><td>have/has + V3</td><td>so far, already, yet, recently, since, for, over the past + khoảng</td></tr><tr><td>HT hoàn thành tiếp diễn</td><td>have/has been + V-ing</td><td>for, since, all morning (nhấn mạnh đang kéo dài)</td></tr><tr><td>Quá khứ hoàn thành</td><td>had + V3</td><td>by the time + QKĐ, before/after + QKĐ, already (trong câu quá khứ)</td></tr><tr><td>Tương lai hoàn thành</td><td>will have + V3</td><td>by + mốc tương lai, by the time + HTĐ</td></tr><tr><td>Tương lai đơn</td><td>will + V</td><td>next, upcoming, soon, tomorrow, as of + ngày trong tương lai</td></tr></table>" },
    { h: "Tương lai trong mệnh đề thời gian & các dấu hiệu dễ nhầm", html: "<p>Sau <b>when, once, as soon as, before, after, until, by the time, if</b> khi nói về tương lai → dùng <b>hiện tại đơn</b> (hoặc <b>hiện tại hoàn thành</b> để nhấn mạnh đã xong), <b>không</b> dùng will. Mệnh đề chính vẫn dùng will / câu mệnh lệnh.</p><ul><li><i><b>Once</b> the contract <b>is signed</b>, we <b>will send</b> you a copy.</i></li><li><i>Please call HR <b>as soon as</b> you <b>have received</b> the offer letter.</i></li></ul><p>Các dấu hiệu dễ nhầm:</p><ul><li><b>as of</b> + ngày = “kể từ ngày”: ngày trong tương lai → will (<i>As of July 1, the policy <b>will take</b> effect</i>); ngày đã qua → hiện tại hoặc hiện tại hoàn thành (<i>As of last Monday, the office <b>has moved</b></i>).</li><li><b>recently / lately</b> → hiện tại hoàn thành (hoặc quá khứ đơn với recently); <b>so far / up to now / over the past five years</b> → hiện tại hoàn thành.</li><li><b>upcoming, next, coming</b> → tương lai: <i>the <b>upcoming</b> meeting <b>will be held</b>…</i></li><li><b>currently, at the moment</b> → hiện tại tiếp diễn; <b>since + quá khứ đơn</b> trong mệnh đề phụ, mệnh đề chính dùng hiện tại hoàn thành: <i>Sales <b>have risen</b> since the price <b>was</b> reduced.</i></li></ul>" },
    { h: "Mẹo làm bài TOEIC", html: "<ul><li>Câu chọn thì: <b>quét dấu hiệu thời gian trước</b>, rồi mới xem lựa chọn. Không có dấu hiệu → xem thì của động từ còn lại trong câu.</li><li><b>by the time</b>: nhìn thì của vế còn lại – quá khứ đơn → <b>had V3</b>; hiện tại đơn → <b>will have V3</b>.</li><li>Sau <b>when / once / as soon as / before / until</b> nói về tương lai → loại <b>will</b> ngay.</li><li>Có <b>for / since</b> và việc vẫn đang diễn ra → <b>have been V-ing</b> hoặc have V3; không bao giờ là quá khứ đơn hay hiện tại đơn.</li><li>Part 6: thì phải khớp với <b>ngữ cảnh cả đoạn</b> (ngày gửi e-mail, sự kiện đã / sắp diễn ra), không chỉ câu chứa chỗ trống.</li></ul>" }
  ],
  examples: [
    { en: "By the time the lawyer arrived, both parties <b>had</b> already <b>signed</b> the agreement.", vi: "Khi luật sư đến thì hai bên đã ký thỏa thuận rồi." },
    { en: "By next month, we <b>will have hired</b> all the seasonal staff.", vi: "Đến tháng sau, chúng tôi sẽ tuyển xong toàn bộ nhân viên thời vụ." },
    { en: "The HR team <b>has been reviewing</b> applications <b>since</b> Monday.", vi: "Phòng nhân sự đã và đang xem xét hồ sơ từ thứ Hai." },
    { en: "<b>Once</b> the contract <b>is</b> signed, we <b>will send</b> you a copy.", vi: "Ngay khi hợp đồng được ký, chúng tôi sẽ gửi bạn một bản." },
    { en: "<b>As of</b> July 1, the new overtime policy <b>will take</b> effect.", vi: "Kể từ ngày 1 tháng Bảy, chính sách làm thêm giờ mới sẽ có hiệu lực." },
    { en: "<b>So far</b>, twelve employees <b>have signed up</b> for the wellness program.", vi: "Đến nay đã có mười hai nhân viên đăng ký chương trình chăm sóc sức khỏe." }
  ],
  vocab: [
    "clause|n|/klɔːz/|điều khoản|provision|Please read the payment clause carefully.|Vui lòng đọc kỹ điều khoản thanh toán.",
    "renewal|n|/rɪˈnjuːəl/|sự gia hạn|extension|The lease is up for renewal next month.|Hợp đồng thuê sẽ đến hạn gia hạn vào tháng sau.",
    "expire|v|/ɪkˈspaɪə(r)/|hết hạn|run out|The contract had expired before we noticed it.|Hợp đồng đã hết hạn trước khi chúng tôi nhận ra.",
    "terminate|v|/ˈtɜːmɪneɪt/|chấm dứt (hợp đồng)|end|Either party may terminate the agreement with 30 days' notice.|Một trong hai bên có thể chấm dứt thỏa thuận nếu báo trước 30 ngày.",
    "amendment|n|/əˈmendmənt/|bản sửa đổi, sự sửa đổi|revision|The lawyers have been working on the amendment since Monday.|Các luật sư đã soạn bản sửa đổi từ thứ Hai.",
    "legally binding|adj|/ˌliːɡəli ˈbaɪndɪŋ/|có hiệu lực ràng buộc về pháp lý|enforceable|Once signed, the agreement will be legally binding.|Sau khi ký, thỏa thuận sẽ có hiệu lực ràng buộc về pháp lý.",
    "draft|v|/drɑːft/|soạn thảo (bản nháp)|prepare|Our lawyer will have drafted the contract by Friday.|Luật sư của chúng tôi sẽ soạn xong hợp đồng trước thứ Sáu.",
    "as of|prep|/ˈæz əv/|kể từ (ngày)|starting from|As of June 1, the office will open at 8 a.m.|Kể từ ngày 1 tháng Sáu, văn phòng sẽ mở cửa lúc 8 giờ sáng.",
    "signatory|n|/ˈsɪɡnətri/|bên ký kết, người ký|—|All signatories must initial each page.|Tất cả các bên ký phải ký tắt vào từng trang.",
    "breach|n|/briːtʃ/|sự vi phạm (hợp đồng)|violation|Late delivery would be a breach of contract.|Giao hàng trễ sẽ là hành vi vi phạm hợp đồng.",
    "terms and conditions|n|/ˌtɜːmz ən kənˈdɪʃnz/|các điều khoản và điều kiện|terms|Read the terms and conditions before you sign.|Hãy đọc các điều khoản và điều kiện trước khi ký.",
    "obligation|n|/ˌɒblɪˈɡeɪʃn/|nghĩa vụ|duty|The supplier has fulfilled all its obligations so far.|Đến nay nhà cung cấp đã hoàn thành mọi nghĩa vụ."
  ],
  exercises: [
    { id: "s2-l5-ex0", p: 5, lvl: 2, q: "By the time the inspector arrived, the staff ___ all the safety documents.", c: ["prepare", "have prepared", "had prepared", "will have prepared"], a: 2, e: "“By the time + quá khứ đơn (arrived)” → việc chuẩn bị xong trước đó: quá khứ hoàn thành <b>had prepared</b>.", t: "thi" },
    { id: "s2-l5-ex1", p: 5, lvl: 2, q: "By the end of next month, the legal team ___ the review of all supplier contracts.", c: ["completes", "has completed", "will have completed", "had completed"], a: 2, e: "“By + mốc tương lai (the end of next month)” → tương lai hoàn thành: <b>will have completed</b>.", t: "thi" },
    { id: "s2-l5-ex2", p: 5, lvl: 2, q: "The two companies ___ the terms of the merger since early March, and talks are still continuing.", c: ["have been negotiating", "are negotiating", "negotiated", "will negotiate"], a: 0, e: "“since early March” + việc vẫn đang tiếp diễn (“talks are still continuing”) → hiện tại hoàn thành tiếp diễn: <b>have been negotiating</b>.", t: "hoan-thanh" },
    { id: "s2-l5-ex3", p: 5, lvl: 2, q: "Please notify the HR department as soon as you ___ the signed contract.", c: ["receive", "will receive", "received", "would receive"], a: 0, e: "Sau “as soon as” nói về tương lai dùng hiện tại đơn, không dùng will → <b>receive</b>.", t: "thi" },
    { id: "s2-l5-ex4", p: 5, lvl: 2, q: "The new leave policy ___ effective as of next Monday.", c: ["became", "has become", "will become", "had become"], a: 2, e: "“as of next Monday” = kể từ thứ Hai tới (tương lai) → <b>will become</b>.", t: "thi" },
    { id: "s2-l5-ex5", p: 5, lvl: 2, q: "Our department ___ three new legal assistants so far this year.", c: ["hires", "has hired", "had hired", "will have hired"], a: 1, e: "“so far this year” (tính đến nay, năm chưa hết) → hiện tại hoàn thành: <b>has hired</b>.", t: "hoan-thanh" },
    { id: "s2-l5-ex6", p: 5, lvl: 2, q: "Before Ms. Han joined our company last year, she ___ as a recruiter for a staffing agency.", c: ["works", "has worked", "had worked", "will work"], a: 2, e: "Việc làm recruiter xảy ra <b>trước</b> một việc quá khứ khác (joined last year) → quá khứ hoàn thành: <b>had worked</b>.", t: "thi" },
    { id: "s2-l5-ex7", p: 5, lvl: 2, q: "The upcoming compliance training ___ in the main conference room on Friday.", c: ["was held", "has been held", "will be held", "had been held"], a: 2, e: "“upcoming” (sắp tới) và “on Friday” → tương lai; buổi đào tạo được tổ chức → <b>will be held</b>.", t: "thi" },
    { id: "s2-l5-ex8", p: 5, lvl: 2, q: "Sales of the new software ___ steadily since the price was reduced in April.", c: ["rise", "rose", "have risen", "will rise"], a: 2, e: "Mệnh đề chính đi với “since + quá khứ đơn” → hiện tại hoàn thành: <b>have risen</b>.", t: "hoan-thanh" },
    { id: "s2-l5-ex9", p: 2, lvl: 2, say: "Have you been waiting long for your interview?", c: ["Only about ten minutes.", "Yes, the interview was long.", "I'll wait for the bus."], a: 0, e: "Câu hỏi đã chờ lâu chưa (have been V-ing) → trả lời thời lượng: <b>Only about ten minutes</b>. Hai câu còn lại lặp từ “interview”, “long”, “wait” để gây bẫy.", t: "hoi-dap" }
  ]
});

TOEIC.addLesson({
  id: "s2-l6", stage: 2, unit: "u2", order: 5, minutes: 25, title: "Bài 8. Bị động nâng cao",
  sections: [
    { h: "Bị động ở thì hoàn thành, tiếp diễn và với động từ khuyết thiếu", html: "<p>Công thức gốc vẫn là <b>be + V3</b>; chỉ cần chia <b>be</b> theo thì:</p><table><tr><th>Thì / dạng</th><th>Bị động</th><th>Ví dụ</th></tr><tr><td>Hiện tại hoàn thành</td><td>have / has <b>been</b> + V3</td><td>The proposal <b>has been approved</b>.</td></tr><tr><td>Quá khứ hoàn thành</td><td>had <b>been</b> + V3</td><td>The files <b>had been archived</b> before the audit.</td></tr><tr><td>Tương lai hoàn thành</td><td>will have <b>been</b> + V3</td><td>All staff <b>will have been trained</b> by May.</td></tr><tr><td>Tiếp diễn</td><td>am / is / are / was <b>being</b> + V3</td><td>The policy <b>is being revised</b>.</td></tr><tr><td>Modal</td><td>can / must / should / may + <b>be</b> + V3</td><td>Forms <b>must be signed</b> in ink.</td></tr><tr><td>Modal quá khứ</td><td>should / must + <b>have been</b> + V3</td><td>The report <b>should have been sent</b> yesterday.</td></tr></table><p>Nhận diện nhanh: <b>been</b> luôn đi sau have/has/had; <b>being</b> luôn đi sau am/is/are/was/were.</p>" },
    { h: "Bị động + to V và bị động vẫn có tân ngữ", html: "<p><b>be + V3 + to V</b> là mẫu rất hay gặp trong thông báo:</p><ul><li><b>be expected / scheduled / supposed to</b> V: <i>The merger <b>is expected to be completed</b> in June.</i></li><li><b>be required / asked / advised / encouraged / allowed / permitted to</b> V: <i>Visitors <b>are required to wear</b> badges.</i></li><li>Nếu chủ ngữ là vật, phần to V cũng thường bị động: <i>The contract is expected <b>to be signed</b></i> (không phải “to sign”).</li></ul><p><b>Động từ có hai tân ngữ</b> (give, offer, send, award, grant, assign) khi bị động <b>vẫn còn một tân ngữ</b> phía sau: <i>All new hires <b>are given</b> a laptop.</i> – <i>Ms. Vu <b>was offered</b> the position.</i> Tương tự với <b>name / appoint / elect / consider</b> + chức danh: <i>Mr. Cho <b>was appointed</b> director.</i> Đừng thấy có danh từ phía sau mà vội chọn chủ động!</p>" },
    { h: "be + V3 + giới từ (học theo cụm)", html: "<table><tr><th>Cụm</th><th>Nghĩa</th><th>Cụm</th><th>Nghĩa</th></tr><tr><td>be pleased / satisfied <b>with</b></td><td>hài lòng với</td><td>be located / based <b>in</b></td><td>nằm ở, đặt trụ sở ở</td></tr><tr><td>be involved / engaged <b>in</b></td><td>tham gia vào</td><td>be interested <b>in</b></td><td>quan tâm đến</td></tr><tr><td>be committed / dedicated <b>to</b> + N / V-ing</td><td>tận tâm với</td><td>be accustomed / used <b>to</b> + N / V-ing</td><td>quen với</td></tr><tr><td>be equipped <b>with</b></td><td>được trang bị</td><td>be composed <b>of</b></td><td>gồm có</td></tr><tr><td>be known <b>for</b></td><td>nổi tiếng về</td><td>be associated <b>with</b></td><td>gắn liền với</td></tr><tr><td>be exposed <b>to</b></td><td>tiếp xúc với</td><td>be divided <b>into</b></td><td>được chia thành</td></tr></table><p>Chú ý: <b>be committed to / be dedicated to / be accustomed to</b> + <b>V-ing</b>, không phải V nguyên mẫu (to là giới từ).</p>" },
    { h: "Mẹo làm bài TOEIC", html: "<ul><li><b>Chủ động hay bị động?</b> Nhìn sau chỗ trống: có <b>tân ngữ</b> → chủ động; không có (giới từ, by, trạng từ, dấu chấm, to V) → bị động. Ngoại lệ: động từ hai tân ngữ (give, offer, send, award) bị động vẫn có danh từ phía sau.</li><li>Động từ <b>không có tân ngữ</b> (occur, happen, arrive, expire, remain, rise, take place) <b>không bao giờ</b> bị động: loại ngay “is expired”, “was occurred”.</li><li>Sau <b>has / have / had</b> mà câu bị động → <b>been</b> + V3; sau <b>is / are</b> mà việc đang diễn ra → <b>being</b> + V3.</li><li><b>Bẫy Part 1:</b> <i>is/are <b>being</b> + V3</i> = có người <b>đang</b> làm (tranh phải có người hành động); <i>has/have <b>been</b> + V3</i> = việc <b>đã xong</b>, đồ vật đang ở trạng thái đó (tranh thường không có người). <i>The chairs <b>have been arranged</b></i> (ghế đã được xếp sẵn) ≠ <i>The chairs <b>are being arranged</b></i> (ai đó đang xếp ghế).</li></ul>" }
  ],
  examples: [
    { en: "The revised travel policy <b>has been approved</b> by the board.", vi: "Chính sách công tác sửa đổi đã được hội đồng quản trị phê duyệt." },
    { en: "The contract <b>must be signed</b> by both parties before May 1.", vi: "Hợp đồng phải được hai bên ký trước ngày 1 tháng Năm." },
    { en: "The new policy <b>is expected to reduce</b> overtime costs.", vi: "Chính sách mới được kỳ vọng sẽ giảm chi phí làm thêm giờ." },
    { en: "Our headquarters <b>is located in</b> the central business district.", vi: "Trụ sở chính của chúng tôi nằm ở khu thương mại trung tâm." },
    { en: "All employees <b>were given</b> a copy of the revised handbook.", vi: "Tất cả nhân viên đều được phát một cuốn sổ tay đã sửa đổi." },
    { en: "The meeting room <b>is being cleaned</b> now, but the chairs <b>have</b> already <b>been arranged</b>.", vi: "Phòng họp đang được dọn dẹp, nhưng ghế thì đã được xếp sẵn rồi." }
  ],
  vocab: [
    "notify|v|/ˈnəʊtɪfaɪ/|thông báo (chính thức)|inform|Staff will be notified of any schedule changes by e-mail.|Nhân viên sẽ được thông báo qua e-mail về mọi thay đổi lịch.",
    "revise|v|/rɪˈvaɪz/|sửa đổi, chỉnh lại|amend|The travel policy has been revised twice this year.|Chính sách công tác đã được sửa đổi hai lần trong năm nay.",
    "verify|v|/ˈverɪfaɪ/|xác minh, kiểm chứng|confirm|All expense claims must be verified by a manager.|Mọi đề nghị thanh toán chi phí phải được quản lý xác minh.",
    "archive|v|/ˈɑːkaɪv/|lưu trữ (hồ sơ)|file|Old contracts are archived in the basement.|Các hợp đồng cũ được lưu trữ dưới tầng hầm.",
    "allocate|v|/ˈæləkeɪt/|phân bổ|assign|A larger budget has been allocated to staff training.|Một khoản ngân sách lớn hơn đã được phân bổ cho việc đào tạo nhân viên.",
    "stationery|n|/ˈsteɪʃənri/|văn phòng phẩm|office supplies|Stationery is kept in the cabinet next to the printer.|Văn phòng phẩm được để trong tủ cạnh máy in.",
    "facility|n|/fəˈsɪləti/|cơ sở, khu nhà (phục vụ một mục đích)|building|The new training facility is located in Thu Duc.|Cơ sở đào tạo mới nằm ở Thủ Đức.",
    "shred|v|/ʃred/|hủy (giấy tờ) bằng máy cắt giấy|destroy|Confidential documents must be shredded after use.|Tài liệu mật phải được hủy bằng máy cắt giấy sau khi dùng.",
    "be accustomed to|phr|/bi əˈkʌstəmd tə/|quen với (+ N / V-ing)|be used to|She is accustomed to working under pressure.|Cô ấy đã quen làm việc dưới áp lực.",
    "be dedicated to|phr|/bi ˈdedɪkeɪtɪd tə/|tận tâm với (+ N / V-ing)|be committed to|Our team is dedicated to improving customer service.|Đội của chúng tôi tận tâm cải thiện dịch vụ khách hàng.",
    "be equipped with|phr|/bi ɪˈkwɪpt wɪð/|được trang bị|be fitted with|Every meeting room is equipped with a projector.|Mỗi phòng họp đều được trang bị máy chiếu.",
    "be composed of|phr|/bi kəmˈpəʊzd əv/|gồm có, được tạo thành từ|consist of|The committee is composed of five senior managers.|Ủy ban gồm năm quản lý cấp cao."
  ],
  exercises: [
    { id: "s2-l6-ex0", p: 5, lvl: 2, q: "The revised contract ___ by both parties, so the project can begin immediately.", c: ["has signed", "has been signed", "is signing", "had signed"], a: 1, e: "Hợp đồng được ký (bị động), sau chỗ trống là “by both parties”, kết quả liên quan hiện tại → <b>has been signed</b>.", t: "bi-dong" },
    { id: "s2-l6-ex1", p: 5, lvl: 2, q: "All visitors ___ to wear identification badges while on the premises.", c: ["require", "are required", "requiring", "have required"], a: 1, e: "Mẫu <b>be required to V</b> (được yêu cầu làm gì) → <b>are required</b> to wear. “have required” là chủ động, sai nghĩa.", t: "bi-dong" },
    { id: "s2-l6-ex2", p: 5, lvl: 2, q: "Expense reports must ___ within thirty days of the business trip.", c: ["submit", "be submitted", "submitted", "be submitting"], a: 1, e: "Báo cáo được nộp, sau chỗ trống không có tân ngữ → modal bị động <b>must be submitted</b>.", t: "bi-dong" },
    { id: "s2-l6-ex3", p: 5, lvl: 2, q: "The new branch office is conveniently ___ near the central train station.", c: ["locate", "locating", "located", "location"], a: 2, e: "Cụm <b>be located</b> (near / in / at) = nằm ở → is conveniently <b>located</b>.", t: "bi-dong" },
    { id: "s2-l6-ex4", p: 5, lvl: 2, q: "The board members were very pleased ___ the results of the annual audit.", c: ["with", "to", "of", "for"], a: 0, e: "Cụm <b>be pleased with</b> + sự việc = hài lòng với.", t: "bi-dong" },
    { id: "s2-l6-ex5", p: 5, lvl: 2, q: "The merger agreement is expected ___ by the end of the month.", c: ["finalize", "to finalize", "to be finalized", "finalizing"], a: 2, e: "be expected + to V; thỏa thuận <b>được</b> hoàn tất (có “by the end of the month”, không có tân ngữ) → <b>to be finalized</b>. “to finalize” sai vì thỏa thuận không tự hoàn tất việc gì.", t: "bi-dong" },
    { id: "s2-l6-ex6", p: 5, lvl: 2, q: "Ms. Patel ___ the employee handbook before it was distributed to new hires.", c: ["revised", "was revised", "has been revised", "being revised"], a: 0, e: "Sau chỗ trống có tân ngữ “the employee handbook” và Ms. Patel là người làm → chủ động: <b>revised</b>.", t: "bi-dong" },
    { id: "s2-l6-ex7", p: 5, lvl: 2, q: "The office lease ___ next month, so we need to decide whether to renew it.", c: ["expires", "is expired", "was expired", "expiring"], a: 0, e: "“expire” là nội động từ (không có tân ngữ) nên <b>không</b> dùng bị động; “next month” → <b>expires</b> (lịch cố định). “expiring” thiếu trợ động từ.", t: "bi-dong" },
    { id: "s2-l6-ex8", p: 5, lvl: 2, q: "All new hires ___ a two-day orientation before they start work.", c: ["give", "are given", "giving", "have given"], a: 1, e: "give có hai tân ngữ (give sb sth); nhân viên mới <b>được</b> cho dự định hướng → bị động vẫn có tân ngữ “a two-day orientation” phía sau: <b>are given</b>.", t: "bi-dong" },
    { id: "s2-l6-ex9", say: "The documents have been arranged on the desk.", q: "Nghe câu mô tả tranh và chọn nghĩa đúng.", c: ["Tài liệu đã được xếp sẵn trên bàn.", "Tài liệu đang được ai đó xếp lên bàn.", "Có người đang ký tài liệu trên bàn.", "Tài liệu đang được cất vào ngăn kéo."], a: 0, e: "“<b>have been arranged</b>” = <b>đã được</b> xếp (trạng thái xong) – tranh chỉ cần có tài liệu nằm ngay ngắn, không cần người. Nếu là “are <b>being</b> arranged” thì mới có người đang xếp.", t: "bi-dong" }
  ]
});

TOEIC.addLesson({
  id: "s2-l7", stage: 2, unit: "u2", order: 6, minutes: 25, title: "Bài 9. Đại từ nâng cao",
  sections: [
    { h: "Đại từ phản thân & đại từ sở hữu", html: "<table><tr><th>Chủ ngữ</th><th>Tân ngữ</th><th>TT sở hữu (+ N)</th><th>ĐT sở hữu (đứng một mình)</th><th>Phản thân</th></tr><tr><td>I</td><td>me</td><td>my</td><td>mine</td><td>myself</td></tr><tr><td>you</td><td>you</td><td>your</td><td>yours</td><td>yourself / yourselves</td></tr><tr><td>he</td><td>him</td><td>his</td><td>his</td><td>himself</td></tr><tr><td>she</td><td>her</td><td>her</td><td>hers</td><td>herself</td></tr><tr><td>it</td><td>it</td><td>its</td><td>—</td><td>itself</td></tr><tr><td>we</td><td>us</td><td>our</td><td>ours</td><td>ourselves</td></tr><tr><td>they</td><td>them</td><td>their</td><td>theirs</td><td>themselves</td></tr></table><p><b>Phản thân</b> dùng khi: (1) tân ngữ <b>chính là</b> chủ ngữ: <i>She introduced <b>herself</b>.</i> (2) <b>nhấn mạnh</b> – đứng sau chủ ngữ hoặc cuối câu, bỏ đi câu vẫn đủ: <i>The CEO <b>herself</b> signed the letter.</i> / <i>He reviewed the contract <b>himself</b>.</i> (3) <b>by + phản thân</b> = một mình, không ai giúp: <i>by <b>himself</b></i> = <i>on <b>his own</b></i>.</p><p><b>Đại từ sở hữu</b> = tính từ sở hữu + danh từ đã nhắc: <i>Their proposal is cheaper, but <b>ours</b> (= our proposal) is faster.</i> Cũng gặp trong <i>a colleague <b>of mine</b></i>.</p>" },
    { h: "another, other, the other, others, the others", html: "<table><tr><th>Từ</th><th>Theo sau</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td><b>another</b></td><td>N số ít (hoặc đứng một mình)</td><td>một … khác (không xác định)</td><td><i>Please use <b>another</b> room.</i></td></tr><tr><td><b>other</b></td><td>N số nhiều / không đếm được</td><td>… khác</td><td><i><b>other</b> applicants, <b>other</b> information</i></td></tr><tr><td><b>the other</b></td><td>N số ít hoặc số nhiều</td><td>cái / người còn lại (đã xác định)</td><td><i>One copy is for you; <b>the other</b> is for HR.</i></td></tr><tr><td><b>others</b></td><td>đứng một mình (= other + N số nhiều)</td><td>những người / cái khác</td><td><i>Some prefer e-mail; <b>others</b> prefer calls.</i></td></tr><tr><td><b>the others</b></td><td>đứng một mình</td><td>tất cả những người / cái còn lại</td><td><i>Two staff stayed; <b>the others</b> left.</i></td></tr></table><p><b>each other / one another</b> = lẫn nhau (làm tân ngữ, không làm chủ ngữ): <i>The two lawyers have known <b>each other</b> for years.</i></p><p><b>one / ones</b> thay cho danh từ đếm được đã nhắc: <i>The old printers were replaced with new <b>ones</b>.</i> – <i>This contract is longer than the previous <b>one</b>.</i></p>" },
    { h: "those who, those of, anyone / anything", html: "<ul><li><b>those who</b> + V số nhiều = những người mà: <i><b>Those who</b> <b>wish</b> to attend must register.</i> (không viết “they who” hay “them who”)</li><li><b>anyone who</b> + V số ít = bất kỳ ai: <i><b>Anyone who</b> <b>needs</b> help should call HR.</i> – <b>whoever</b> đã bao gồm “who”: <i><b>Whoever</b> needs help…</i></li><li><b>that of / those of</b> thay cho danh từ đã nhắc trong câu so sánh: <i>Our prices are lower than <b>those of</b> our competitors.</i> (those = the prices) – <i>Her salary is higher than <b>that of</b> her predecessor.</i></li><li><b>anything / anyone</b> trong câu khẳng định = bất cứ thứ / ai: <i>Feel free to ask me <b>anything</b>.</i>; <b>something / someone</b> = một thứ / một người nào đó.</li></ul>" },
    { h: "Mẹo làm bài TOEIC", html: "<ul><li>4 lựa chọn là <b>him / his / himself / he</b>: chỗ trống trước danh từ → tính từ sở hữu; sau động từ / giới từ → tân ngữ; sau <b>by</b> hoặc tân ngữ trùng chủ ngữ hoặc cuối câu đã đủ thành phần → <b>phản thân</b>.</li><li>Chỗ trống đứng một mình làm chủ ngữ / tân ngữ thay cho “sở hữu + danh từ” → đại từ sở hữu <b>mine, ours, theirs</b>.</li><li><b>another</b> + số ít, <b>other</b> + số nhiều; có “the” → đã xác định (cái còn lại). Có <b>one … </b>trong nhóm hai thì vế sau là <b>the other</b>.</li><li>Trước <b>who</b> chỉ chọn <b>those</b> (số nhiều) hoặc <b>anyone</b> (số ít): xem động từ sau who để quyết định.</li><li>So sánh hai sự vật → cần <b>that of / those of</b> để không so sánh “giá” với “công ty”.</li></ul>" }
  ],
  examples: [
    { en: "The CEO <b>herself</b> will announce the new hiring policy.", vi: "Chính giám đốc điều hành sẽ công bố chính sách tuyển dụng mới." },
    { en: "Ms. Ito drafted the whole proposal <b>by herself</b>.", vi: "Cô Ito đã tự mình soạn toàn bộ bản đề xuất." },
    { en: "Their offer is higher, but <b>ours</b> includes a better benefits package.", vi: "Đề nghị của họ cao hơn, nhưng đề nghị của chúng tôi có gói phúc lợi tốt hơn." },
    { en: "One photocopier is broken, and <b>the other</b> is out of toner.", vi: "Một máy photocopy bị hỏng, còn máy kia thì hết mực." },
    { en: "<b>Those who</b> wish to attend the workshop must register by Friday.", vi: "Những ai muốn dự buổi hội thảo phải đăng ký trước thứ Sáu." },
    { en: "The two firms have collaborated with <b>each other</b> for over a decade.", vi: "Hai công ty đã hợp tác với nhau hơn mười năm." }
  ],
  vocab: [
    "delegate|v|/ˈdelɪɡeɪt/|giao (việc), ủy thác|hand over|Good managers delegate routine tasks to their teams.|Người quản lý giỏi giao những việc thường ngày cho nhóm của mình.",
    "collaborate|v|/kəˈlæbəreɪt/|hợp tác|work together|The two departments collaborated with each other on the project.|Hai phòng đã hợp tác với nhau trong dự án.",
    "counterpart|n|/ˈkaʊntəpɑːt/|người đồng cấp (ở phía bên kia)|equivalent|Our CEO met her counterpart from the Korean firm.|Giám đốc điều hành của chúng tôi đã gặp người đồng cấp bên công ty Hàn Quốc.",
    "assign|v|/əˈsaɪn/|phân công, giao|allocate|Each intern is assigned to a different department.|Mỗi thực tập sinh được phân về một phòng khác nhau.",
    "oversee|v|/ˌəʊvəˈsiː/|giám sát, trông coi|supervise|Mr. Lim oversees the hiring process himself.|Ông Lim tự mình giám sát quy trình tuyển dụng.",
    "liaison|n|/liˈeɪzn/|người liên lạc, đầu mối|contact person|Ms. Ha acts as a liaison between the two offices.|Cô Hà làm đầu mối liên lạc giữa hai văn phòng.",
    "successor|n|/səkˈsesə(r)/|người kế nhiệm|replacement|The board has chosen a successor to the retiring CEO.|Hội đồng quản trị đã chọn người kế nhiệm vị giám đốc sắp nghỉ hưu.",
    "predecessor|n|/ˈpriːdəsesə(r)/|người tiền nhiệm|—|Her ideas are very different from those of her predecessor.|Ý tưởng của cô ấy rất khác với ý tưởng của người tiền nhiệm.",
    "subordinate|n|/səˈbɔːdɪnət/|cấp dưới|staff member|A good manager lets subordinates solve problems by themselves.|Người quản lý giỏi để cấp dưới tự giải quyết vấn đề.",
    "independently|adv|/ˌɪndɪˈpendəntli/|một cách độc lập|on one's own|Senior staff are expected to work independently.|Nhân viên cấp cao được kỳ vọng làm việc độc lập.",
    "respectively|adv|/rɪˈspektɪvli/|lần lượt, theo thứ tự tương ứng|—|Mr. Vo and Ms. Le were promoted to director and manager, respectively.|Ông Võ và bà Lê lần lượt được thăng chức lên giám đốc và trưởng phòng.",
    "mutual|adj|/ˈmjuːtʃuəl/|lẫn nhau, chung|shared|The contract was ended by mutual agreement.|Hợp đồng được chấm dứt theo thỏa thuận chung của hai bên."
  ],
  exercises: [
    { id: "s2-l7-ex0", p: 5, lvl: 2, q: "Mr. Grant prefers to review all supplier contracts ___ rather than delegate the task.", c: ["him", "his", "himself", "he"], a: 2, e: "Câu đã đủ thành phần (review all supplier contracts); chỗ trống ở cuối dùng để nhấn mạnh “tự mình” → đại từ phản thân <b>himself</b>.", t: "dai-tu" },
    { id: "s2-l7-ex1", p: 5, lvl: 2, q: "Our proposal was accepted, but ___ was rejected because it exceeded the budget.", c: ["their", "theirs", "them", "they"], a: 1, e: "Chỗ trống làm chủ ngữ thay cho “their proposal” → đại từ sở hữu <b>theirs</b>. “their” phải có danh từ đi kèm; “they was” sai.", t: "dai-tu" },
    { id: "s2-l7-ex2", p: 5, lvl: 2, q: "Only ___ who have completed the safety training may operate the equipment.", c: ["those", "these", "them", "they"], a: 0, e: "<b>those who</b> + V số nhiều = những người mà. “them / they who” không dùng; “these” không đi với who.", t: "dai-tu" },
    { id: "s2-l7-ex3", p: 5, lvl: 2, q: "Of the two applicants we interviewed, one lacked experience, and ___ did not speak Japanese.", c: ["another", "the other", "others", "other"], a: 1, e: "Nhóm chỉ có hai người: “one … <b>the other</b>” (người còn lại, đã xác định). “another” dùng khi còn nhiều lựa chọn chưa xác định.", t: "dai-tu" },
    { id: "s2-l7-ex4", p: 5, lvl: 2, q: "Some employees prefer to work from home, while ___ prefer to come to the office.", c: ["other", "the other", "others", "another"], a: 2, e: "Chỗ trống đứng một mình làm chủ ngữ số nhiều (prefer) = “những người khác” → <b>others</b>. “other” phải có danh từ đi kèm; “the other”, “another” chỉ một người, không hợp với “prefer”.", t: "dai-tu" },
    { id: "s2-l7-ex5", p: 5, lvl: 2, q: "___ who wishes to apply for the internal position should submit a form by Friday.", c: ["Anyone", "Those", "Whoever", "Each"], a: 0, e: "Động từ “wishes” số ít → <b>Anyone</b> who (bất kỳ ai). “Those who” cần động từ số nhiều (wish); “Whoever” đã bao gồm who nên không đi với who.", t: "dai-tu" },
    { id: "s2-l7-ex6", p: 5, lvl: 2, q: "The two lawyers have known ___ since they studied at the same university.", c: ["each other", "themselves", "theirs", "another"], a: 0, e: "Hai người quen biết <b>lẫn nhau</b> → <b>each other</b>. “themselves” là mỗi người tự biết mình, sai nghĩa.", t: "dai-tu" },
    { id: "s2-l7-ex7", p: 5, lvl: 2, q: "The old printers on the second floor were replaced with new ___ that can scan in color.", c: ["one", "ones", "it", "them"], a: 1, e: "Thay cho danh từ số nhiều “printers” đã nhắc, sau tính từ “new” → <b>ones</b>. “one” là số ít; “it / them” không đứng sau tính từ.", t: "dai-tu" },
    { id: "s2-l7-ex8", p: 5, lvl: 2, q: "Our consulting fees are considerably lower than ___ of our main competitors.", c: ["that", "those", "them", "these"], a: 1, e: "So sánh phí với phí: <b>those</b> of = the fees of (số nhiều). “that of” dùng cho danh từ số ít; “them” không đi với of trong so sánh.", t: "dai-tu" },
    { id: "s2-l7-ex9", p: 2, lvl: 2, say: "Is this your laptop or Mr. Kim's?", c: ["I think it's his.", "Yes, it's a new laptop.", "Mr. Kim is in a meeting."], a: 0, e: "Câu hỏi lựa chọn (của bạn hay của ông Kim) → <b>I think it's his</b> (đại từ sở hữu his = Mr. Kim's laptop). Câu hỏi lựa chọn không trả lời bằng Yes; câu cuối chỉ lặp tên Mr. Kim.", t: "hoi-dap" }
  ]
});

TOEIC.addTest({
  id: "cp-s2-u2", kind: "checkpoint", title: "Kiểm tra Chặng 2 – Ngữ pháp Part 5 cốt lõi",
  desc: "Ôn lại từ loại qua đuôi từ, danh từ người & vật, tính từ -ed/-ing, hòa hợp chủ ngữ – động từ, thì nâng cao, bị động nâng cao và đại từ nâng cao (bài 2–9).",
  groups: [
    { id: "cp-s2-u2-g0", p: 5, lvl: 2, q: "The ___ of the new hiring policy will begin next quarter.", c: ["implement", "implementation", "implemented", "implementable"], a: 1, e: "Sau mạo từ “The” và trước “of” cần danh từ; đuôi <b>-tion</b> là danh từ → <b>implementation</b>.", t: "tu-loai" },
    { id: "cp-s2-u2-g1", p: 5, lvl: 2, q: "Ms. Song handled the client's complaint very ___.", c: ["profession", "professional", "professionally", "professionalism"], a: 2, e: "Bổ nghĩa cho động từ “handled” (đứng sau “very”, cuối câu) → trạng từ đuôi <b>-ly</b>: <b>professionally</b>.", t: "tu-loai" },
    { id: "cp-s2-u2-g2", p: 5, lvl: 2, q: "Please attach a copy of your résumé to the ___ form.", c: ["apply", "applicant", "application", "applied"], a: 2, e: "Danh từ ghép cố định <b>application form</b> (mẫu đơn đăng ký). “applicant” là người, không ghép với “form”.", t: "tu-loai" },
    { id: "cp-s2-u2-g3", p: 5, lvl: 2, q: "The staff were ___ by the CEO's announcement of a company-wide bonus.", c: ["excite", "exciting", "excited", "excitement"], a: 2, e: "Nhân viên <b>cảm thấy</b> phấn khích (bị tác động bởi thông báo) → <b>excited</b>. “exciting” mô tả thông báo gây phấn khích.", t: "tu-loai" },
    { id: "cp-s2-u2-g4", p: 5, lvl: 2, q: "The results of the annual performance appraisal ___ sent to each employee by e-mail last week.", c: ["was", "were", "has", "is"], a: 1, e: "Chủ ngữ thật là “The results” (số nhiều), “last week” → quá khứ, bị động → <b>were</b> sent.", t: "hoa-hop" },
    { id: "cp-s2-u2-g5", p: 5, lvl: 2, q: "Neither the employees nor their supervisor ___ informed about the schedule change yesterday.", c: ["was", "were", "are", "be"], a: 0, e: "neither A nor B → chia theo B (“their supervisor”, số ít); “yesterday” → quá khứ → <b>was</b>.", t: "hoa-hop" },
    { id: "cp-s2-u2-g6", p: 5, lvl: 2, q: "By the time the new manager arrives next week, we ___ all the paperwork.", c: ["complete", "completed", "will have completed", "had completed"], a: 2, e: "“By the time + hiện tại đơn (arrives)” nói về tương lai → tương lai hoàn thành: <b>will have completed</b>.", t: "thi" },
    { id: "cp-s2-u2-g7", p: 5, lvl: 2, q: "The software update will be installed as soon as the technician ___.", c: ["arrives", "will arrive", "arrived", "arriving"], a: 0, e: "Sau “as soon as” nói về tương lai dùng hiện tại đơn → <b>arrives</b>.", t: "thi" },
    { id: "cp-s2-u2-g8", p: 5, lvl: 2, q: "The renovation of the third floor ___ by the end of the year.", c: ["is expected to complete", "is expected to be completed", "expects completing", "expected completing"], a: 1, e: "Việc cải tạo <b>được</b> hoàn thành (có “by the end of the year”, không có tân ngữ) → be expected + to be V3: <b>is expected to be completed</b>.", t: "bi-dong" },
    { id: "cp-s2-u2-g9", p: 5, lvl: 2, q: "The training materials ___ to all participants before the workshop begins.", c: ["distributed", "will distribute", "will be distributed", "distributing"], a: 2, e: "Tài liệu <b>được</b> phát, sau chỗ trống không có tân ngữ mà là “to all participants” → bị động tương lai: <b>will be distributed</b>.", t: "bi-dong" },
    { id: "cp-s2-u2-g10", p: 5, lvl: 2, q: "Ms. Chen prefers to handle client complaints ___ instead of passing them to her assistant.", c: ["she", "her", "herself", "hers"], a: 2, e: "Câu đã đủ thành phần, cần nhấn mạnh “tự mình” → đại từ phản thân <b>herself</b>.", t: "dai-tu" },
    { id: "cp-s2-u2-g11", p: 5, lvl: 2, q: "Of the two candidates, one has more experience, but ___ has better language skills.", c: ["another", "other", "the other", "others"], a: 2, e: "Nhóm chỉ có hai ứng viên: “one … <b>the other</b>” (người còn lại). “others” là số nhiều, không hợp với “has”.", t: "dai-tu" },
    { id: "cp-s2-u2-g12", p: 5, lvl: 2, q: "Our technicians ___ the elevators between 9 A.M. and noon tomorrow, so please use the stairs during that time.", c: ["inspected", "have inspected", "will be inspecting", "had inspected"], a: 2, e: "“between 9 A.M. and noon tomorrow” + “during that time” → việc đang diễn ra trong một khoảng thời gian tương lai: tương lai tiếp diễn <b>will be inspecting</b>.", t: "thi" },
    { id: "cp-s2-u2-g13", p: 5, lvl: 2, q: "Ms. Park ___ the Busan office next Tuesday; her train ticket was booked yesterday.", c: ["visited", "has visited", "is visiting", "had visited"], a: 2, e: "Lịch hẹn cá nhân đã sắp xếp (vé đã đặt) cho “next Tuesday” → hiện tại tiếp diễn diễn tả tương lai: <b>is visiting</b>. Các lựa chọn khác là thì quá khứ / hoàn thành, mâu thuẫn với “next Tuesday”.", t: "thi" },
    { id: "cp-s2-u2-g14", p: 5, lvl: 2, q: "The CEO announced last week that the company ___ its headquarters to Busan the following spring.", c: ["moves", "has moved", "would move", "had moved"], a: 2, e: "Động từ tường thuật quá khứ “announced” + “the following spring” (tương lai nhìn từ quá khứ) → will lùi thành <b>would move</b>.", t: "thi" }
  ]
});
